<script setup lang="ts">
import {geographyGames,type GeographyGame} from '~/data/geography/gameQuestions'
import {makeGeographyQuestions,type GeographyQuestion} from '~/utils/geography/games'
const props=defineProps<{mapAnswer?:{code:string;requestId:number};game?:GeographyGame;embedded?:boolean}>()
const emit=defineEmits<{mapTask:[task:{label:string}|null];mapVisit:[];mapReveal:[code:string]}>()
const {countries,statistics,status}=useGeographyAtlas()
const {estimates:latestPopulation,status:populationStatus}=usePopulationEstimates()
const mode=ref<GeographyGame>(props.game||'guess')
watch(()=>props.game,value=>{if(value)mode.value=value})
const questions=ref<GeographyQuestion[]>([]),index=ref(0),score=ref(0),answer=ref<string|null>(null),started=ref(false)
const current=computed(()=>questions.value[index.value]),finished=computed(()=>started.value&&index.value>=questions.value.length)
const isCorrect=computed(()=>!!answer.value&&answer.value===current.value?.answer)
const canRevealAnswer=computed(()=>mode.value==='map'&&!!answer.value&&!!current.value&&!isCorrect.value)
const label=(code:string)=>countries.value.find(c=>c.cca3===code)?.nameHy||'Տվյալը հասանելի չէ'
function announce(){emit('mapTask',started.value&&!finished.value&&mode.value==='map'&&!answer.value&&current.value?{label:current.value.prompt}:null)}
function start(){questions.value=makeGeographyQuestions(mode.value,countries.value,statistics.value,Math.random,latestPopulation.value);index.value=0;score.value=0;answer.value=null;started.value=questions.value.length>0;announce()}
function submit(code:string){if(answer.value||!current.value||finished.value)return;answer.value=code;if(code===current.value.answer)score.value+=10;announce()}
function revealAnswer(){if(canRevealAnswer.value&&current.value)emit('mapReveal',current.value.answer)}
function next(){index.value++;answer.value=null;announce()}
function stop(){started.value=false;questions.value=[];emit('mapTask',null)}
watch(()=>props.mapAnswer,a=>{if(a&&mode.value==='map'&&started.value)submit(a.code)})
watch(mode,stop)
onBeforeUnmount(()=>emit('mapTask',null))
</script>
<template><section id="globe-games" class="geo-section" :class="{'game-embedded':embedded}" aria-labelledby="geo-games-title"><header><p v-if="!embedded" class="geo-kicker">ՍՈՎՈՐԻՐ՝ ԽԱՂԱԼՈՎ</p><h2 id="geo-games-title">{{embedded?geographyGames.find(g=>g.id===mode)?.title:'Աշխարհագրական խաղեր'}}</h2><p>Ընտրիր խաղը։ Հարցերը պատահական են և չեն կրկնվում նույն խաղաշրջանում։</p></header><div class="geography-play"><div v-if="!embedded" class="geo-filters" role="group" aria-label="Խաղի ընտրություն"><button v-for="g in geographyGames" :key="g.id" class="geo-button" :aria-pressed="mode===g.id" @click="mode=g.id">{{g.title}}</button></div><p>{{geographyGames.find(g=>g.id===mode)?.description}}</p><button v-if="!started" class="geo-button" :disabled="status!=='ready'||(mode==='larger'&&populationStatus==='loading')" @click="start">Սկսել խաղը</button><p v-if="mode==='larger'&&populationStatus==='loading'" role="status">Ստուգում ենք բնակչության ամենաթարմ տվյալները…</p><p v-if="mode==='larger'&&populationStatus==='error'" class="geo-note">Թարմացումը հասանելի չէ․ օգտագործվում են պահված տվյալները՝ հարցում նշված տարեթվով։</p><p v-if="status==='error'" role="status">Երկրների տվյալները հասանելի չեն․ փորձիր թարմացնել էջը։</p>
<article v-if="started" class="panel geo-card geography-question"><div class="game-meta"><span>Միավորներ՝ {{score}}</span><span>{{Math.min(index+1,questions.length)}} / {{questions.length}}</span></div><div class="geo-progress" aria-hidden="true"><span :style="{width:`${100*index/questions.length}%`}"/></div><template v-if="finished"><h3>Ճանապարհորդությունն ավարտված է</h3><p>Վաստակեցիր {{score}} միավոր՝ հնարավոր {{questions.length*10}}-ից։</p><button class="geo-button game-replay" @click="start">Խաղալ կրկին</button></template><template v-else-if="current"><h3>{{current.prompt}}</h3><CountryFlag v-if="current.flag" class="quiz-flag" :code="current.flag"/><div v-if="mode!=='map'" class="game-options"><button v-for="code in current.options" :key="code" class="geo-button" :class="{'answer-right':answer&&code===current.answer,'answer-wrong':answer===code&&code!==current.answer}" :disabled="!!answer" @click="submit(code)">{{label(code)}}</button></div><button v-else-if="!answer" class="geo-button" @click="emit('mapVisit')">Գնալ երկրագնդի մոտ ↑</button><div v-if="answer" class="game-feedback" :class="{'is-correct':isCorrect,'is-incorrect':!isCorrect}" role="status"><div v-if="isCorrect" class="correct-answer-heading"><span class="correct-answer-icon" aria-hidden="true"><svg width="24" height="24" viewBox="0 0 24 24" fill="none"><path d="m5 12 4 4L19 6" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg></span><strong>Ճիշտ պատասխան է։</strong><span class="correct-answer-points">+10 միավոր</span></div><strong v-else>Այս անգամ՝ ոչ։</strong><strong class="feedback-country">{{label(current.answer)}}</strong><p>{{current.explanation}}</p><div class="geo-actions"><button v-if="canRevealAnswer" class="geo-button" @click="revealAnswer">Տեսնել ճիշտ պատասխանը քարտեզի վրա</button><button class="geo-button" @click="next">{{index+1===questions.length?'Տեսնել արդյունքը':'Հաջորդ հարցը →'}}</button></div></div></template><div class="geo-actions"><button class="geo-button" @click="stop">Ավարտել խաղաշրջանը</button></div></article><p class="geo-note">Յուրաքանչյուր խաղաշրջանում՝ {{mode==='guess'?15:8}} հարց և 10 միավոր յուրաքանչյուր ճիշտ պատասխանի համար։ Հարցերը չեն կրկնվում։ Քարտեզի խաղն օգտագործում է քարտեզում առկա երկրները։</p></div></section></template>
<style scoped>
.game-feedback.is-incorrect{border-color:#e88791;background:#c94f6010}

.game-feedback.is-correct{width:fit-content;max-width:100%;border-color:#73c6a0;background:linear-gradient(135deg,#236b483d,#102d251a)}.correct-answer-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.correct-answer-icon{display:grid;place-items:center;width:40px;height:40px;flex-shrink:0;border-radius:50%;color:#b3f2d1;background:#73c6a026;border:1px solid #73c6a080}.game-feedback.is-correct .correct-answer-heading strong{color:#b3f2d1;font-size:clamp(18px,3vw,23px);line-height:1.4}.correct-answer-points{font-size:12px;font-weight:750;color:#b3f2d1;background:#73c6a01c;padding:6px 10px;border-radius:20px;white-space:nowrap}.game-feedback .feedback-country{display:block;margin-top:12px;font-size:20px;line-height:1.5;overflow-wrap:anywhere}.game-feedback.is-correct .feedback-country{color:#f0fff7}.game-feedback.is-correct p{max-width:48ch;color:#c0dacf}
.game-replay{margin-top:20px}.game-embedded{display:grid;grid-template-columns:.9fr 1.1fr;margin:0!important;padding:0!important}.game-embedded header{padding:34px;background:radial-gradient(ellipse at 0 0,#dfc38f14,transparent 75%)}.game-embedded header h2{font-size:clamp(23px,2.8vw,32px);margin:0 0 14px}.game-embedded .geography-play{padding:30px;border-left:1px solid #8997c02b;min-width:0}.game-embedded .geography-question{border:0;background:transparent;padding:0}.game-embedded .geography-play>.geo-button{width:100%;margin-top:20px;justify-content:center;background:#dfc38f;color:#111827}.geography-play>.geo-note{margin-top:20px}@media(max-width:800px){.game-embedded{grid-template-columns:1fr}.game-embedded header{padding:24px}.game-embedded .geography-play{padding:24px;border-left:0;border-top:1px solid #8997c02b}}.game-meta{display:flex;justify-content:space-between;gap:12px;font-size:12px;color:#dfc38f}.geography-question{margin:20px 0;max-width:850px}.geography-question h3{font-size:20px;margin:20px 0}.game-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin:24px 0}.game-options .geo-button{min-height:60px;text-align:left;justify-content:start}.quiz-flag{width:100px!important;height:65px!important;margin:20px 0}.game-feedback{padding:20px;border:1px solid #dfc38f55;border-radius:12px;margin:20px 0}.game-feedback strong{color:#dfc38f}.game-feedback p{margin:12px 0}.game-options .answer-right{border-color:#73c6a0;color:#a3e1c5;opacity:1}.game-options .answer-wrong{border-color:#de8589;color:#e6a1a4;opacity:1}@media(max-width:500px){.game-options{grid-template-columns:1fr}}</style>
